    'help.tokens.title': "Tokenuri de automatizare",
    'help.tokens.body': "Chei API pentru scripturi care rulează fără browser: un cron care verifică ce hosturi sunt offline, un pas de CI care repornește un serviciu, o sondă de monitorizare.\n\n`read` permite citirea statusului, a hosturilor și a sesiunilor. `run` permite rularea unei comenzi pe un host. Atât: fără jurnal de audit, fără setări și niciodată un host care cere 2FA.\n\nOrice token expiră (max. 365 de zile), iar apelurile lui apar în audit ca token:<nume>.",
    'help.guardrail.title': "Guardrail pentru comenzi",
    'help.guardrail.body': "Reguli regex pentru comenzi periculoase, ex. `rm\\s+-rf\\s+/` sau `^reboot`. O comandă care se potrivește fie cere „ești sigur?” (confirm), fie e refuzată (block).\n\nSe aplică mereu la „Rulează pe hosturi” și la tokenuri. În terminal merge doar unde integrarea shell e activă — o plasă de siguranță pentru greșeli, nu o barieră pentru cineva hotărât.",
    'help.signingKey.title': "Cheia de semnare a agenților",
    'help.signingKey.body': "Agenții instalează doar update-uri semnate cu cheia asta, ca cine controlează gateway-ul să nu poată împinge pe furiș cod arbitrar pe hosturi.\n\nCheia se generează pentru acest deployment la prima pornire. Fă-i backup: dacă o pierzi, trebuie să re-înrolezi toate hosturile. Blocheaz-o cu o frază de acces dacă vrei ca update-urile să ceară un om.",
    'help.enrollGroups.title': "Grupuri de înrolare",
    'help.enrollGroups.body': "O singură comandă de instalare pentru multe mașini: fiecare host care o rulează ajunge în același grup, cu aceleași setări (tag-uri, 2FA). Utilă pentru o infrastructură întreagă, un script cloud-init sau un play Ansible.\n\nLinkul grupului are propria expirare și poate fi revocat oricând.",
    'help.deployKeyPolicy.title': "Politica pentru chei de deploy",
    'help.deployKeyPolicy.body': "Întărire opțională pentru cheile SSH de deploy create în Toolbox, oprită implicit:\n• 2FA obligatoriu pe hosturile sursă — un host care ține o cheie de deploy își poate atinge țintele, deci trebuie să ceară el însuși 2FA înainte să se genereze o cheie pe el.\n• Chei restricționate obligatoriu — refuză deploy-urile cu shell complet; fiecare cheie trebuie să aibă `restrict` sau o comandă forțată.",
    'help.smtp.title': "Alerte pe email (SMTP)",
    'help.smtp.body': "WebTerm îți scrie când e nevoie de un om: IP blocat, login dintr-un loc nou, host căzut sau revenit, cheie de host schimbată, update de agent refuzat, disc aproape plin, backup eșuat și altele.\n\nFolosește butonul Test după salvare. Fiecare eveniment e limitat în timp, ca un host instabil să nu-ți umple inbox-ul.",
    'help.webhook.title': "Webhook pentru alerte",
    'help.webhook.body': "Aceleași alerte ca pe email, trimise ca JSON la un URL: un incoming webhook Slack sau Discord, Teams, ntfy sau propriul tău endpoint. Merge cu sau fără SMTP.",
    'help.resourceAlerts.title': "Alerte de resurse",
    'help.resourceAlerts.body': "Praguri pentru CPU, RAM și disc pe fiecare host (0 = oprit). CPU-ul trebuie să stea peste prag 3 cicluri, deci vârfurile scurte sunt ignorate. Primești o alertă când o valoare trece pragul și una când revine — niciodată un șir.",
    'help.forwardDomain.title': "Domeniul pentru port forwarding",
    'help.forwardDomain.body': "Forward-urile îți deschid o interfață web care ascultă doar pe un host (Grafana pe :3000, pagina de admin a unui router) la https://<nume>.<acest domeniu>, prin login-ul WebTerm — fără să deschizi porturi.\n\nAi nevoie de o înregistrare DNS wildcard (*.domeniu → acest server) și de un certificat wildcard (DNS-01).",
    'help.directBackup.title': "Backup pe serverul tău",
    'help.directBackup.body': "Copiază backup-ul criptat pe un server pe care îl controlezi, prin SFTP (SSH) sau FTPS — de ex. un NAS. Folosește un utilizator dedicat care poate scrie doar într-un folder. Arhiva e criptată înainte să plece, deci destinația nu vede niciodată datele.",
    'help.updatesBadge.title': "Badge-ul de update-uri",
    'help.updatesBadge.body': "Agentul întreabă periodic managerul de pachete al hostului (apt, dnf, pacman, zypper, apk) câte update-uri așteaptă. Badge-ul arată numărul — toate sau doar cele de securitate, cum alegi. Îl poți opri per host dacă o mașină e înghețată intenționat.",
    'help.wol.title': "Wake-on-LAN",
    'help.wol.body': "Pornește o mașină oprită. WebTerm cere ALTUI agent, online în același LAN, să trimită pachetul magic. Adresa MAC e învățată din diagnosticul hostului cât timp a fost pornit.\n\nWake-on-LAN trebuie activat în BIOS/UEFI și pe placa de rețea a mașinii.",
    'help.tags.title': "Tag-uri",
    'help.tags.body': "Etichete libere (prod, debian, web…) pentru filtrarea listei de hosturi și pentru alegerea țintelor în „Rulează pe hosturi”. Singure nu schimbă niciun comportament.",
    'help.require2fa.title': "Cere 2FA (step-up)",
    'help.require2fa.body': "Fiecare conexiune nouă la acest host — și acțiunile riscante pe el — îți cere să dovedești din nou că ești tu cu un al doilea factor: passkey dacă ai unul, altfel SSO sau un cod TOTP. Parola singură nu ajunge — fără passkey sau TOTP, configurează întâi unul în Setări → Autentificare & 2FA. După un step-up reușit rămâne deschisă o fereastră scurtă; un terminal rămâne deblocat cel mult 60 de minute, apoi cere din nou.\n\nTokenurile de automatizare nu pot ajunge niciodată la un astfel de host.",
    'help.credentialPolicy.title': "Credențiale stocate",
    'help.credentialPolicy.body': "Cum ține WebTerm parola/cheia SSH a acestui host:\n• Stocate — criptate pe gateway, folosite automat.\n• Cerute — nu se stochează, le tastezi la fiecare conectare.\n• Efemere — folosite o dată pentru instalarea agentului, apoi șterse.\n\n„Uită” șterge definitiv credențialele stocate.",
    'help.enrollTtl.title': "Valabilitatea linkului de instalare",
