    'host.autostartLingerTitle': "Activat, dar doar după un login",
    'host.autostartLingerBody': "systemd pornește agentul pentru {user} abia după ce userul ăsta se loghează. Ca să pornească la boot, rulează o dată ca root pe host: loginctl enable-linger {user}",
    'help.autostart.title': "Pornește la boot",
    'help.autostart.body': "Dacă agentul revine singur după un reboot al hostului. Fără asta, un reboot lasă hostul offline în WebTerm până intră cineva prin SSH și pornește agentul.\n\n• systemd — un serviciu de user (Restart=always). Pornește la boot doar cu linger activ pentru userul agentului (`loginctl enable-linger <user>`, cere root o dată).\n• cron — o linie @reboot plus un watchdog la fiecare minut.\n\nActivează instalează același mecanism ca instalatorul; Dezactivează îl scoate, dar nu atinge agentul care rulează.",
    'sidebar.noAutostartTitle': "Agentul nu pornește la boot — după un reboot hostul rămâne offline",
