    // walkthrough de primă rulare (Walkthrough.tsx) — 7 pași, redeschis din „?" / Setări
    'walkthrough.step1.title': "Bine ai venit în WebTerm",
    'walkthrough.step1.body': "Terminalele tale și toată infrastructura, în browser. Turul ăsta rapid îți arată ce poți face — durează sub un minut.",
    'walkthrough.step2.title': "Adaugă un host",
    'walkthrough.step2.body': "Instalează agentul pentru tot setul — sesiuni persistente, fișiere, servicii, Docker, port-forward-uri și serial. Preferi SSH sau un jump host? Nu instalezi nimic: ai sesiuni de terminal și port-forward-uri, dar acele sesiuni se închid dacă gateway-ul repornește, iar fișierele, serviciile, Docker și serialul cer agentul.",
    'walkthrough.step3.title': "Sesiuni și terminalul",
    'walkthrough.step3.body': "Deschide multe taburi, aranjează-le în split view sau scoate o sesiune în fereastra ei. Sesiunile se reconectează singure — supraviețuiesc unui laptop adormit.",
    'walkthrough.step4.title': "Lipește sau trage fișiere",
    'walkthrough.step4.body': "Pe un host cu agent, lipești o imagine sau tragi un fișier și ajunge în ~/.webterm/inbox, cu calea scrisă la prompt — gata de dat unui CLI ca Claude Code.",
    'walkthrough.step5.title': "Uneltele sesiunii",
    'walkthrough.step5.body': "Deasupra terminalului unui host cu agent stă o bară de unelte: editezi fișiere în Monaco, vezi git, deschizi port-forward-uri, gestionezi servicii și Docker. Snippet-urile (Alt+S), istoricul comenzilor și al clipboard-ului (Ctrl+Shift+V) sunt la o scurtătură distanță. Conexiunile la baze de date, cheile SSH și biblioteca de comenzi stau în tab-ul Toolbox al hostului.",
    'walkthrough.step6.title': "Securitate din start",
    'walkthrough.step6.body': "Hosturile sensibile pot cere un al doilea factor: un host marcat cere step-up 2FA înainte să acționeze. Te autentifici cu passkey, iar sesiunile inactive se blochează singure.",
    'walkthrough.step7.title': "Gata, ești pregătit",
    'walkthrough.step7.body': "Pentru scurtături, dă click oriunde în afara terminalului și apasă ? (în terminal, ? doar se tastează). Transferurile de fișiere apar în widgetul din dreapta-jos. Redeschide turul din panoul de scurtături ? sau din Setări → Preferințe.",
    'walkthrough.next': "Înainte",
    'walkthrough.back': "Înapoi",
    'walkthrough.getStarted': "Gata",
    'walkthrough.skip': "Mai târziu",
    'walkthrough.dontShow': "Nu mai arăta asta",
    'walkthrough.dotLabel': "Pasul {k} din {n}",
    'walkthrough.progress': "Progresul turului",
    'walkthrough.replayHelp': "Reia turul de bun venit",
    'walkthrough.settingsTitle': "Turul de bun venit",
    'walkthrough.settingsToggle': "Arată turul de bun venit pentru sesiuni noi",
    'walkthrough.replayButton': "Reia turul",
    // Sfaturi contextuale (coach tips): callout-uri mici, non-modale, arătate o dată, lângă UI.
    'tips.gotIt': "Am înțeles",
    'tips.dismiss': "Închide sfatul",
    'tips.addhost.agent.title': "Mod agent: tot pachetul",
    'tips.addhost.agent.body': "Instalează agentul cu comanda afișată în continuare, iar hostul capătă sesiuni persistente, navigator de fișiere, Docker, servicii și redirecționări de port.",
    'tips.addhost.ssh.title': "Hosturi SSH și jump",
    'tips.addhost.ssh.body': "Hosturile SSH îți dau sesiuni de terminal și port forwarding fără să instalezi nimic pe țintă — dar acele sesiuni trăiesc în memoria gateway-ului și se închid când acesta repornește. Sesiunile persistente, fișierele, serviciile, Docker și consola serială cer agentul. Un host jump ajunge la țintă printr-un bastion în care ai deja încredere.",
    'tips.terminal.paste.title': "Lipește sau trage fișiere aici",
    'tips.terminal.paste.body': "Lipește o captură sau trage un fișier peste terminal — ajunge pe host, iar calea e tastată pentru tine.",
    'tips.toolbar.title': "Uneltele sesiunii",
    'tips.toolbar.body': "Fișiere, git, redirecționări de port, Docker și servicii sunt aici sus. Treci cu mouse-ul peste orice buton ca să vezi ce face.",
    'tips.resetTitle': "Sfaturi contextuale",
